entries[152788] = { ["name"] = "Lightforged Warframe", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses your Lightforged Warframe. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Army of the Light\n- Exalted\nSell Price:\n\"The Army of the Light conducts quick, brutal hit-and-run attacks using these agile war machines.\"\nVendor:\nVindicator Jaelaana\nZone:\nArgus\nFaction:\nArmy of the Light - Exalted\nCost:" }
entries[152789] = { ["name"] = "Shackled Ur'zul", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses your Shackled Ur'zul.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nSell Price:\n\"Formed from the tormented bodies and souls of fallen members of the Army of the Light, the Ur'zul is both fascinating and horrifying.\"\nDrop:\nArgus the Unmaker (Mythic)" }
entries[152790] = { ["name"] = "Vile Fiend", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Vile Fiend.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nSell Price:\n\"Infused with acidic blood through a terrifying ritual, you can feel your control over this beast is tenuous at best.\"\nDrop:\nHoundmaster KerraxZone:\nAntoran Wastes" }
