entries[152814] = { ["name"] = "Maddened Chaosrunner", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Maddened Chaosrunner.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\n\n\"The Army of the Light could only save so many of Argus' native species; countless numbers were lost to chaos.\"\nDrop:\nWrangler Kravos\nZone:\nEredath" }
entries[152815] = { ["name"] = "Antoran Gloomhound", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses your Antoran Gloomhound.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Sargeras' own hound was maybe once a felstalker, but over the years the Dark Titan reforged and reshaped his companion into something much more powerful. When, at last, he was pleased with his creation, he set about creating more of the hounds, and imbuing them with shadow and flame.\"\nAchievement:\nGlory of the Argus Raider\nCategory:\nDungeons & Raids" }
entries[152816] = { ["name"] = "Antoran Charhound", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses your Antoran Charhound.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nSell Price:\n\"Sargeras' own hound was maybe once a felstalker, but over the years the Dark Titan reforged and reshaped his companion into something much more powerful. When, at last, he was pleased with his creation, he set about creating more of the hounds, and imbuing them with shadow and flame.\"\nDrop:\nShatug\nZone:\nAntorus, the Burning Throne" }
