entries[153193] = { ["name"] = "Baarut the Brisk", ["text"] = "Binds when picked up\nUnique\nToy\nMount\n(Account-wide)\nUse: Summons a ridable spectral talbuk on Argus. This is a very, VERY fast mount. (20 Min Cooldown)\nAvailable with the release of Legion Remix: Argus Eternal.\nSell Price:" }
entries[153194] = { ["name"] = "Legion Communication Orb", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Allows you to see far into the distance and grants the ability to summon beacons there to attract Legion forces. (10 Min Cooldown)\nAvailable with the release of Legion Remix: Argus Eternal." }
